namespace NotificationsApp.Services;

public class Notification
{
    public int Id { get; set; }
    public string Message { get; set; } = string.Empty;
    public DateTime Timestamp { get; set; }
    public bool IsRead { get; set; }
}

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with fake initial data.
        _notifications.AddRange(new[]
        {
            new Notification { Id = _nextId++, Message = "Welcome to the app!", Timestamp = DateTime.UtcNow.AddMinutes(-30) },
            new Notification { Id = _nextId++, Message = "Your profile was updated.", Timestamp = DateTime.UtcNow.AddMinutes(-15) },
            new Notification { Id = _nextId++, Message = "New feature: dark mode is available.", Timestamp = DateTime.UtcNow.AddMinutes(-5) },
        });

        // Background thread that simulates new notifications arriving.
        _ = Task.Run(async () =>
        {
            var messages = new[]
            {
                "Someone commented on your post.",
                "You have a new follower!",
                "Deployment succeeded.",
                "Disk usage above 80%.",
                "Scheduled maintenance tonight at 11 PM.",
                "Your export is ready for download.",
            };

            var rng = new Random();
            while (true)
            {
                await Task.Delay(TimeSpan.FromSeconds(rng.Next(4, 10)));
                lock (_lock)
                {
                    _notifications.Add(new Notification
                    {
                        Id = _nextId++,
                        Message = messages[rng.Next(messages.Length)],
                        Timestamp = DateTime.UtcNow,
                    });
                }
            }
        });
    }

    /// <summary>Returns all notifications (newest first).</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.OrderByDescending(n => n.Timestamp).ToList();
        }
    }

    /// <summary>Returns only notifications newer than the given id.</summary>
    public List<Notification> GetNewerThan(int lastSeenId)
    {
        lock (_lock)
        {
            return _notifications
                .Where(n => n.Id > lastSeenId)
                .OrderByDescending(n => n.Timestamp)
                .ToList();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using NotificationsApp.Services
@inject NotificationService NotificationSvc
@inject PersistentComponentState ApplicationState
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (_notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@_notifications.Count</span>
    }
</h1>

@if (_notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (_notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in _notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <div>
                    <strong>@n.Message</strong>
                    <br />
                    <small class="text-muted">@n.Timestamp.ToString("g")</small>
                </div>
                <span class="badge bg-secondary">#@n.Id</span>
            </li>
        }
    </ul>
}

@code {
    private List<Notification>? _notifications;
    private PersistingComponentStateSubscription _persistSub;
    private CancellationTokenSource? _pollCts;

    protected override void OnInitialized()
    {
        // During prerendering the state won't exist yet, so we load from the
        // service. When the page becomes interactive the persisted snapshot is
        // restored, avoiding a second fetch.
        _persistSub = ApplicationState.RegisterOnPersisting(PersistNotifications);

        if (ApplicationState.TryTakeFromJson<List<Notification>>("notifications", out var restored))
        {
            _notifications = restored;
        }
        else
        {
            _notifications = NotificationSvc.GetAll();
        }
    }

    private Task PersistNotifications()
    {
        ApplicationState.PersistAsJson("notifications", _notifications);
        return Task.CompletedTask;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        // OnAfterRender is never called during static SSR — only once the
        // circuit is live. Start polling here so it only runs interactively.
        if (firstRender)
        {
            _pollCts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_pollCts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            try
            {
                await Task.Delay(TimeSpan.FromSeconds(5), ct);
            }
            catch (TaskCanceledException)
            {
                break;
            }

            var lastId = _notifications?.Count > 0
                ? _notifications.Max(n => n.Id)
                : 0;

            var newer = NotificationSvc.GetNewerThan(lastId);
            if (newer.Count > 0)
            {
                _notifications = _notifications is not null
                    ? [..newer, .._notifications]
                    : newer;

                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _persistSub.Dispose();
        _pollCts?.Cancel();
        _pollCts?.Dispose();
    }
}

